import math
M=998244353
def brute(n,A,B):
    ratios=[]
    for x in A:
        ratios.append([(P,x//P) for P in range(1,x+1) if x%P==0 and math.gcd(P,x//P)==1])
    total=0
    def rec(i,seq):
        nonlocal total
        if i==n-1:
            if math.gcd(*seq)==1:
                pr=1
                for s in seq: pr*=s
                total+=pr
            return
        for P,Q in ratios[i]:
            cur=seq[-1]
            if (cur*Q)%P==0:
                nx=cur*Q//P
                if nx<=B: rec(i+1,seq+[nx])
    for s1 in range(1,B+1): rec(0,[s1])
    return total%M, total
