class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: list) -> int:
        bucket = [[] for _ in range(n + 1)]
        for i, (x, y) in enumerate(conflictingPairs):
            a, b = min(x, y), max(x, y)
            bucket[b].append((a, i))
        m = len(conflictingPairs)
        gain = [0] * m
        t1a, t1i, t2a = 0, -1, 0
        T = 0
        for x in range(1, n + 1):
            for a, i in bucket[x]:
                if a > t1a:
                    t2a = t1a
                    t1a, t1i = a, i
                elif a > t2a:
                    t2a = a
            T += x - t1a
            if t1i >= 0:
                gain[t1i] += t1a - t2a
        return T + max(gain) if m else T

