import sys
from functools import lru_cache
def solve(boxes, M, K):
    n=len(boxes)
    @lru_cache(maxsize=None)
    def f(state, rem, bought):
        any_ball=False; best=None
        for t in range(M):
            if rem[t]==0: continue
            any_ball=True
            opts=[0]
            nrem=list(rem); nrem[t]-=1; nrem=tuple(nrem)
            st=list(state)
            for k,(i,tt,c) in enumerate(st):
                if tt==t and c<boxes[i][0]:
                    ns=st[:]; ns[k]=(i,tt,c+1)
                    opts.append(1+f(tuple(sorted(ns)),nrem,bought))
            for i in range(n):
                if bought>>i &1: continue
                ns=st+[(i,t,1)]
                opts.append(1-boxes[i][1]+f(tuple(sorted(ns)),nrem,bought|(1<<i)))
            v=max(opts)
            if best is None or v<best: best=v
        if not any_ball: return 0
        return max(0,best)
    return f((),tuple([K]*M),0)
