def fast(n,m,boxes):
    if m>n: return 0
    if m==1:
        return sum(max(0,v-p) for v,p in boxes)
    bs=sorted(boxes,key=lambda x:-x[0])
    suf=[0]*(n+1)
    for i in range(n-1,-1,-1):
        suf[i]=suf[i+1]+max(0,bs[i][0]-bs[i][1])
    h=[]; sh=0; best=0; k=m-2
    for j in range(n):
        v,p=bs[j]
        if len(h)==k:
            cand=(m-1)-(sh+p)+suf[j+1]
            if cand>best: best=cand
