import sys
from functools import lru_cache
sys.setrecursionlimit(10000)
LIMIT = 130

@lru_cache(maxsize=None)
def G(d, S, c):
    if d == LIMIT or not S:
        return 0
    best = -1
    for q in (c, c + 2):
        fixed = 0
        for v in S:
            if (v + q) % 2 == 1 and (v + q) % 4 == 1:
                fixed += 1
        r = q & 1
        S2 = tuple((v + r) // 2 for v in S if v % 2 == r)
        tot = fixed + G(d + 1, S2, q >> 1)
        if tot > best:
            best = tot
    return best

def solve(A):
    S = tuple(sorted(A))
    return max(G(0, S, 0), G(0, S, 1))

