    data=sys.stdin.read().split()
    n,m=int(data[0]),int(data[1])
    rows=[0]*n
    for i in range(m):
        u=int(data[2+2*i])-1; v=int(data[3+2*i])-1
        rows[u]|=1<<v; rows[v]|=1<<u
    mat=rows[:]
    r=0
    pivrow_col=[]
    is_piv=[False]*n
    for c in range(n):
        sel=-1
        for i in range(r,n):
            if (mat[i]>>c)&1:
                sel=i;break
        if sel<0: continue
        mat[r],mat[sel]=mat[sel],mat[r]
        for j in range(n):
            if j!=r and (mat[j]>>c)&1:
                mat[j]^=mat[r]
        pivrow_col.append((r,c))
        is_piv[c]=True
        r+=1
    basis=[]
    for f in range(n):
        if is_piv[f]: continue
        x=1<<f
        for (i,p) in pivrow_col:
            if (mat[i]>>f)&1:
                x|=1<<p
        basis.append(x)
