class Solution:
    def lenOfVDiagonal(self, grid):
        n = len(grid); m = len(grid[0])
        dirs = [(1,1),(1,-1),(-1,-1),(-1,1)]
        F = []; R = []
        for k in range(4):
            dr, dc = dirs[k]
            rows = range(n) if dr == 1 else range(n-1, -1, -1)
            cols = range(m) if dc == 1 else range(m-1, -1, -1)
            f = [[0]*m for _ in range(n)]
            for i in rows:
                gi = grid[i]; fi = f[i]
                for j in cols:
                    v = gi[j]
                    if v == 1:
                        fi[j] = 1
                    else:
                        pi, pj = i-dr, j-dc
                        if 0 <= pi < n and 0 <= pj < m:
                            p = f[pi][pj]
                            if p:
                                pv = grid[pi][pj]
                                if (v == 2 and pv != 2) or (v == 0 and pv == 2):
                                    fi[j] = p+1
            F.append(f)
            r2 = [[0]*m for _ in range(n)]
            r0 = [[0]*m for _ in range(n)]
            for i in reversed(list(rows)):
                gi = grid[i]
                for j in reversed(list(cols)):
                    v = gi[j]
                    si, sj = i+dr, j+dc
                    inb = 0 <= si < n and 0 <= sj < m
                    if v == 2:
                        r2[i][j] = 1 + (r0[si][sj] if inb else 0)
                    elif v == 0:
                        r0[i][j] = 1 + (r2[si][sj] if inb else 0)
            R.append({2: r2, 0: r0})
        best = 0
        for k in range(4):
            k2 = (k+1) % 4
            f = F[k]
            di, dj = dirs[k2]
            for i in range(n):
                for j in range(m):
                    p = f[i][j]
                    if not p:
                        continue
                    if p > best: best = p
                    v = grid[i][j]
                    e = 0 if v == 2 else 2
                    ni, nj = i+di, j+dj
                    if 0 <= ni < n and 0 <= nj < m:
                        t = p + R[k2][e][ni][nj]
                        if t > best: best = t
        return best

