from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 2)
        for i in range(1, n + 2):
            fact[i] = fact[i - 1] * i

        def ways(o, e, last):
            if o + e == 0:
                return 1
            c = 0
            if last != 1 and o - e in (0, 1):
                c += 1
            if last != 0 and e - o in (0, 1):
                c += 1
            return c * fact[o] * fact[e]

        o = (n + 1) // 2
        e = n // 2
        if ways(o, e, None) < k:
            return []
        rem = list(range(1, n + 1))
        res = []
        last = None
