class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        MOD = 10**9 + 7
        N = m * n
        def S(t):
            return sum(d * (t - d) for d in range(1, t))
        r = n * n * S(m) + m * m * S(n)
        r %= MOD
        a, b = N - 2, k - 2
        num = 1
        den = 1
        for i in range(b):
            num = num * (a - i) % MOD
            den = den * (i + 1) % MOD
        c = num * pow(den, MOD - 2, MOD) % MOD
        return r * c % MOD

