    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        w = []
        for i in range(h):
            j = n - 1 - i
            if i == j:
                w.append(pow(10, i, k))
            else:
                w.append((pow(10, i, k) + pow(10, j, k)) % k)
        S = [0] * (h + 1)
        S[h] = 1
        for i in range(h - 1, -1, -1):
            lo = 1 if i == 0 else 0
            mask = 0
            for r in range(k):
                if S[i + 1] >> r & 1:
                    for d in range(lo, 10):
                        mask |= 1 << ((r + d * w[i]) % k)
            S[i] = mask
        if not (S[0] & 1):
