        t = 0
        left = []
        for i in range(h):
            lo = 1 if i == 0 else 0
            chosen = None
            for d in range(9, lo - 1, -1):
                nt = (t - d * w[i]) % k
                if S[i + 1] >> nt & 1:
                    chosen = d
                    t = nt
                    break
            left.append(chosen)
        s = left + left[:n // 2][::-1]
