import sys
from functools import lru_cache
def main():
    d=sys.stdin.read().split()
    n,m,l=int(d[0]),int(d[1]),int(d[2])
    vals=[int(x) for x in d[3:3+n+m+l]]
    K=n+m+l
    full=(1<<K)-1
    A0=sum(1<<i for i in range(n))
    B0=sum(1<<i for i in range(n,n+m))
    sys.setrecursionlimit(10000)
    @lru_cache(maxsize=None)
    def win(th,ah,turn):
        mine = th if turn==0 else ah
        table = full ^ th ^ ah
        for i in range(K):
            if not (mine>>i)&1: continue
            nm = mine ^ (1<<i)
            nt = table | (1<<i)
            if turn==0:
                nth=nm; nah=ah
            else:
                nth=th; nah=nm
            cand=[None]
            v=vals[i]
            t=nt
            while t:
                lb=t&-t; j=lb.bit_length()-1; t^=lb
                if vals[j]<v: cand.append(j)
            for c in cand:
                if c is None:
                    a,b=nth,nah
                else:
                    if turn==0: a,b=nth|(1<<c),nah
                    else: a,b=nth,nah|(1<<c)
                if not win(a,b,1-turn):
                    return True
        return False
    print("Takahashi" if win(A0,B0,0) else "Aoki")
