    data=sys.stdin.read().split()
    t=int(data[0]); pos=1
    MOD=998244353
    out=[]
    for _ in range(t):
        H=int(data[pos]); W=int(data[pos+1]); pos+=2
        S=data[pos:pos+H]; pos+=H
        N=H+W
        parent=list(range(N)); par=[0]*N
        comps=N
        bad=False
        colflip=[0]*W
        for row in S:
            if row.count('A')%2: bad=True
        if not bad:
            for j in range(W):
                cnt=0
                for i in range(H):
                    if S[i][j]=='A': cnt+=1
                if cnt%2: bad=True; break
        if bad:
            out.append(0); continue
        def find(x):
            path=[]
            while parent[x]!=x:
                path.append(x); x=parent[x]
            root=x
            acc=0
            for node in reversed(path):
                acc^=par[node]
                par[node]=acc
                parent[node]=root
            return root
        for i in range(H):
            row=S[i]
            if i>0:
                for j in range(W):
                    if row[j]=='A': colflip[j]^=1
            P=0
            for j in range(W):
                if j>0 and row[j]=='A': P^=1
                if row[j]=='B':
                    w=1^P^colflip[j]
                    a=i; b=H+j
                    ra=find(a); pa=par[a] if a!=ra else 0
                    rb=find(b); pb=par[b] if b!=rb else 0
                    if ra==rb:
                        if (pa^pb)!=w:
                            bad=True; break
                    else:
                        parent[ra]=rb
                        par[ra]=pa^pb^w
                        comps-=1
            if bad: break
        if bad:
            out.append(0)
        else:
            out.append(pow(2,comps,MOD))
    print("\n".join(map(str,out)))
