import bisect

def _occ(x, s):
    n = len(s)
    if not x:
        return list(range(n + 1))
    m = len(x)
    pi = [0] * m
    k = 0
    for i in range(1, m):
        while k and x[i] != x[k]:
            k = pi[k - 1]
        if x[i] == x[k]:
            k += 1
        pi[i] = k
    res = []
    k = 0
    for i, ch in enumerate(s):
        while k and ch != x[k]:
            k = pi[k - 1]
        if ch == x[k]:
            k += 1
        if k == m:
            res.append(i - m + 1)
            k = pi[k - 1]
    return res

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        f = p.index('*')
        l = p.index('*', f + 1)
        a = p[:f]
        b = p[f + 1:l]
        c = p[l + 1:]
        A = _occ(a, s)
        B = _occ(b, s)
        C = _occ(c, s)
        if not A or not B or not C:
            return -1
        la, lb, lc = len(a), len(b), len(c)
        best = -1
        for k in B:
            ia = bisect.bisect_right(A, k - la) - 1
            if ia < 0:
                continue
            mi = bisect.bisect_left(C, k + lb)
            if mi >= len(C):
                continue
            val = C[mi] + lc - A[ia]
            if best < 0 or val < best:
                best = val
        return best

