    xs = [i+1 for i in range(N) if A[i]=='1']
    bs = [i+1 for i in range(N) if B[i]=='1']
    K = len(xs); m = len(bs)
    if K < m:
        return -1
    INF = 10**9
    def run(T):
        prev = None
        for k in range(K):
            x = xs[k]
            cur = [INF]*m
            for j in range(m):
                if abs(bs[j]-x) > T:
                    continue
                d = bs[j]-x
                c = 1 if (T-d) % 2 else 0
                if k == 0:
                    if j == 0:
                        cur[j] = c
                    continue
                best = INF
                if prev[j] < INF:
                    best = prev[j]
                if j >= 1 and prev[j-1] < INF and (bs[j]-bs[j-1]) <= (x - xs[k-1]):
                    best = min(best, prev[j-1])
                if best < INF:
                    cur[j] = best + c
            prev = cur
        return prev[m-1]
    for T in range(0, 2*N+5):
        r = run(T)
        if r < INF and r < K and r <= T:
            return T
    return -1
