    K = int(data[0]); S = data[1]; T = data[2]
    n, m = len(S), len(T)
    if abs(n - m) > K:
        print("No"); return
    MOD = (1 << 61) - 1
    B = random.randrange(10**6, 10**9)
    N = max(n, m)
    pw = [1] * (N + 1)
    for i in range(N):
        pw[i+1] = pw[i] * B % MOD
    hs = [0] * (n + 1)
    h = 0
    for i, c in enumerate(S.encode()):
        h = (h * B + c) % MOD
        hs[i+1] = h
    ht = [0] * (m + 1)
    h = 0
    for i, c in enumerate(T.encode()):
        h = (h * B + c) % MOD
        ht[i+1] = h
    def lcp(i, j):
        lo, hi = 0, min(n - i, m - j)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            a = (hs[i+mid] - hs[i] * pw[mid]) % MOD
            b = (ht[j+mid] - ht[j] * pw[mid]) % MOD
            if a == b:
                lo = mid
            else:
                hi = mid - 1
        return lo
    prev = {0: lcp(0, 0)}
    if prev[0] == n and n == m:
        print("Yes"); return
    for d in range(1, K + 1):
        cur = {}
        for k in range(-d, d + 1):
            cands = []
            if k in prev: cands.append(prev[k] + 1)
            if k + 1 in prev: cands.append(prev[k + 1] + 1)
