class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        INF = float('inf')
        minv = [INF] * k
        ans = -INF
        p = 0
        for i in range(len(nums) + 1):
            if i > 0:
                p += nums[i - 1]
            r = i % k
            if minv[r] != INF:
                v = p - minv[r]
                if v > ans:
                    ans = v
            if p < minv[r]:
                minv[r] = p
        return int(ans)

