def main():
    N = int(sys.stdin.read().split()[0])
    M = math.isqrt(N)
    sieve = bytearray([1]) * (M + 1)
    sieve[0] = 0
    if M >= 1:
        sieve[1] = 0
    for i in range(2, math.isqrt(M) + 1):
        if sieve[i]:
            sieve[i*i::i] = bytearray(len(range(i*i, M + 1, i)))
    primes = [i for i in range(2, M + 1) if sieve[i]]
    ans = 0
    for p in primes:
        if p ** 8 <= N:
            ans += 1
        else:
            break
    for i, p in enumerate(primes):
        if p * p > M:
            break
        lim = M // p
        cnt = bisect.bisect_right(primes, lim) - (i + 1)
        if cnt > 0:
            ans += cnt
    print(ans)

