class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        NEG = -10**9
        dp = [NEG] * (m + 1)
        dp[0] = 0
        tset = set(targetIndices)
        for i, c in enumerate(source):
            t = i in tset
            new = dp[:]
            for j in range(m + 1):
                v = dp[j]
                if v == NEG:
                    continue
                if t and v + 1 > new[j]:
                    new[j] = v + 1
                if j < m and c == pattern[j] and v > new[j + 1]:
                    new[j + 1] = v
            dp = new
        return max(0, dp[m])

